import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 12;
    static final int INF = 1000000;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static int N, T;
    static char[][] grid1 = new char[MAXN][MAXN];
    static char[][] grid2 = new char[MAXN][MAXN];
    static int[][] A = new int[MAXN][MAXN];
    static int[][][][] B = new int[MAXN][MAXN][MAXN][MAXN];

    static class Edge {
        int a, b, cap, flow;
        public Edge(int a, int b, int cap, int flow) {
            this.a = a;
            this.b = b;
            this.cap = cap;
            this.flow = flow;
        }
    }

    static int n, s, t;
    static int[] d, ptr, q;
    static List<Edge> e = new ArrayList<>();
    static List<Integer>[] g;

    static int get_id(int x, int y) {
        return x * N + y;
    }

    static void add_edge(int a, int b, int cap) {
        Edge e1 = new Edge(a, b, cap, 0);
        Edge e2 = new Edge(b, a, 0, 0);
        g[a].add(e.size()); e.add(e1);
        g[b].add(e.size()); e.add(e2);
    }

    static boolean bfs() {
        int qh = 0, qt = 0;
        q[qt++] = s;
        Arrays.fill(d, -1);
        d[s] = 0;
        while (qh < qt && d[t] == -1) {
            int v = q[qh++];
            for (int id : g[v]) {
                int to = e.get(id).b;
                if (d[to] == -1 && e.get(id).flow < e.get(id).cap) {
                    q[qt++] = to;
                    d[to] = d[v] + 1;
                }
            }
        }
        return d[t] != -1;
    }

    static int dfs(int v, int flow) {
        if (flow == 0) return 0;
        if (v == t) return flow;
        for (; ptr[v] < g[v].size(); ptr[v]++) {
            int id = g[v].get(ptr[v]);
            int to = e.get(id).b;
            if (d[to] != d[v] + 1) continue;
            int pushed = dfs(to, Math.min(flow, e.get(id).cap - e.get(id).flow));
            if (pushed > 0) {
                e.get(id).flow += pushed;
                e.get(id ^ 1).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int max_flow() {
        int flow = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = dfs(s, INF)) > 0) {
                flow += pushed;
            }
        }
        return flow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());

        g = new ArrayList[2 * N * N + 2];
        for (int i = 0; i < g.length; i++) g[i] = new ArrayList<>();
        d = new int[g.length];
        ptr = new int[g.length];
        q = new int[g.length];

        for (int i = 0; i < N; i++) {
            String line = br.readLine();
            grid1[i] = line.toCharArray();
        }
        for (int i = 0; i < N; i++) {
            String line = br.readLine();
            grid2[i] = line.toCharArray();
        }

        for (int i = 0; i < N; i++) {
            Arrays.fill(A[i], INF);
        }

        Queue<int[]> Q = new LinkedList<>();
        for (int x = 0; x < N; x++) {
            for (int y = 0; y < N; y++) {
                if (grid1[x][y] == 'Z') {
                    for (int i = 0; i < 4; i++) {
                        int nx = x + dx[i], ny = y + dy[i];
                        if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y') {
                            A[nx][ny] = 1;
                            Q.offer(new int[]{nx, ny});
                        }
                    }
                }
            }
        }

        while (!Q.isEmpty()) {
            int[] p = Q.poll();
            int x = p[0], y = p[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && A[nx][ny] == INF) {
                    A[nx][ny] = A[x][y] + 1;
                    Q.offer(new int[]{nx, ny});
                }
            }
        }

        for (int x1 = 0; x1 < N; x1++) {
            for (int y1 = 0; y1 < N; y1++) {
                for (int x2 = 0; x2 < N; x2++) {
                    for (int y2 = 0; y2 < N; y2++) {
                        if (grid1[x1][y1] == 'Y' || grid1[x1][y1] == 'Z' || grid1[x2][y2] == 'Y' || grid1[x2][y2] == 'Z') {
                            B[x1][y1][x2][y2] = 0;
                            continue;
                        }
                        for (int i = 0; i < N; i++) {
                            Arrays.fill(A[i], INF);
                        }
                        Queue<int[]> Q2 = new LinkedList<>();
                        A[x1][y1] = 0;
                        Q2.offer(new int[]{x1, y1});
                        int c = 0;
                        while (!Q2.isEmpty()) {
                            int[] p2 = Q2.poll();
                            int x = p2[0], y = p2[1];
                            if (x == x2 && y == y2) {
                                c = 1;
                                break;
                            }
                            if (A[x][y] >= T || A[x][y] >= A[x][y]) continue;
                            for (int i = 0; i < 4; i++) {
                                int nx = x + dx[i], ny = y + dy[i];
                                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && A[nx][ny] == INF && A[x][y] + 1 <= A[nx][ny]) {
                                    A[nx][ny] = A[x][y] + 1;
                                    Q2.offer(new int[]{nx, ny});
                                }
                            }
                        }
                        B[x1][y1][x2][y2] = c;
                    }
                }
            }
        }

        int s = 0;
        int t = 2 * N * N + 1;
        int totalNodes = 2 * N * N + 2;
        // Build network
        for (int i = 0; i < totalNodes; i++) g[i].clear();

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (grid1[i][j] > '0' && grid1[i][j] <= '9') {
                    add_edge(s, 1 + get_id(i, j), grid1[i][j] - '0');
                }
                if (grid2[i][j] > '0' && grid2[i][j] <= '9') {
                    add_edge(N * N + 1 + get_id(i, j), t, grid2[i][j] - '0');
                }
            }
        }

        for (int x1 = 0; x1 < N; x1++) {
            for (int y1 = 0; y1 < N; y1++) {
                for (int x2 = 0; x2 < N; x2++) {
                    for (int y2 = 0; y2 < N; y2++) {
                        if (B[x1][y1][x2][y2] == 0) continue;
                        add_edge(1 + get_id(x1, y1), N * N + 1 + get_id(x2, y2), INF);
                    }
                }
            }
        }

        System.out.println(max_flow());
    }
}

